using Microsoft.EntityFrameworkCore;

// Cosmos DB project context – demonstrates EF Core 9 breaking changes for Cosmos provider.
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=fake==",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // Breaking change 1: EF Core 9 renamed the default discriminator
            // property from "Discriminator" to "$type".
            // For existing documents that already store "Discriminator", you must
            // explicitly configure EF to keep using the old property name.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

// Breaking change 2: EF Core 9 Cosmos provider removed synchronous I/O support.
// All queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.).
class ProductService
{
    private readonly CosmosDbContext _db;
    public ProductService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 – synchronous, now throws InvalidOperationException in EF 9):
    //   var products = _db.Products.Where(p => p.Category == cat).ToList();

    // AFTER (EF Core 9 – must use async):
    public async Task<List<Product>> GetByCategoryAsync(string cat)
        => await _db.Products.Where(p => p.Category == cat).ToListAsync();
}

